void ui_init() {
    eez_flow_init(assets, sizeof(assets), (lv_obj_t **)&objects, sizeof(objects), images, sizeof(images), actions);
}

void ui_tick() {
    // تست ثابت کرد throttle کردنِ eez_flow اثری نداشت → مقصر نیست؛ به حالتِ سالم (هر تیک) برگشت.
    eez_flow_tick();
    // آیتم ۲: هنگام خروج از منو اطلاعات، خروجی‌های دستی به حالت قبل (خاموش) برگردند
    static int16_t prev_screen = -1;
    int16_t cur_page = (g_currentScreen >= 0) ? (g_currentScreen + 1) : -1;
    if (prev_screen == SCREEN_ID_SCREEN_UPDATE && cur_page != SCREEN_ID_SCREEN_UPDATE) {
        extern void fw_info_reset_manual_outputs(void);
        fw_info_reset_manual_outputs();
    }
    // آیتم: ورود به صفحهٔ تنظیماتِ مدیر → وضعیتِ تایمرِ معکوس را تازه کن.
    // (۱) عدد را از روی روزهای واقعیِ گذشته دوباره حساب کن و
    // (۲) پرچمِ «دست‌خورده» را صفر کن؛ تا تا وقتی کاربر اسلایدر را لمس نکرده،
    //     زدنِ «ذخیره» هیچ عددِ جدیدی برای تایمر ننویسد/ری‌استارت نکند.
    if (prev_screen != SCREEN_ID_SCREEN_SETTING_ADMIN && cur_page == SCREEN_ID_SCREEN_SETTING_ADMIN) {
        extern void admin_countdown_panel_open(void);
        admin_countdown_panel_open();
    }
    if (prev_screen == SCREEN_ID_SCREEN_SETTING_ADMIN && cur_page != SCREEN_ID_SCREEN_SETTING_ADMIN) {
        extern void admin_countdown_panel_discard(void);
        admin_countdown_panel_discard();
    }
    // ذخیره صفحه جاری در حافظه RTC Slow برای بازیابی خودکار پس از کرش/هنگ (خروج و ورود)
    if (prev_screen != cur_page) {
        extern void ui_resume_record_screen_exit(int16_t from_screen_id, int16_t to_screen_id);
        extern void ui_resume_record_screen_entry(int16_t screen_id);
        if (prev_screen > 0) {
            ui_resume_record_screen_exit(prev_screen, cur_page);
        }
        if (cur_page > 0) {
            ui_resume_record_screen_entry(cur_page);
        }
    }
    // صفحه اطلاعات را پیش‌ساختن نکن — ساخت سنگین رم داخلی را برای بافرهای WiFi
    // کم می‌کند و مسیر «بروزرسانی → جستجوی شبکه» با SCAN FAILED می‌شکند (دانش فنی).
    prev_screen = cur_page;
    tick_screen(g_currentScreen);
}
